import sys
from typing import List

def max_probability(n: int, p: List[float]) -> float:
    dp = [0.0] * (n + 1)
    dp[0] = 1.0

    for pi in p:
        new_dp = [0.0] * (n + 1)
        for j in range(n + 1):
            if j == 0:
                new_dp[j] = dp[j] * (1 - pi)
            elif j == 1:
                new_dp[j] = dp[j] * pi + dp[j - 1] * (1 - pi)
            else:
                new_dp[j] = dp[j] * pi
        dp = new_dp

    return dp[1]

